<template>
  <el-dialog title="工序作业" :visible.sync="visible" width="736px" top="10vh" custom-class="production-task-dialog" append-to-body :close-on-click-modal="false" :show-close="!busy && !cuttingBusy" :close-on-press-escape="!busy && !cuttingBusy" :before-close="beforeClose" @closed="closed">
    <div v-loading="loading">
      <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon />
      <template v-if="task">
        <div class="ptw-task-summary"><span class="ptw-product-icon"><i class="el-icon-monitor" /></span><div class="ptw-task-identity"><h3>{{ productName }} · {{ task.operation_name_snapshot }}</h3><span>{{ task.work_order && task.work_order.work_order_no }}</span><el-tag size="mini" type="success">{{ target ? target.status_label : '请选择执行对象' }}</el-tag></div><dl><div><dt>产品名称</dt><dd>{{ productName }}</dd></div><div><dt>计划数量</dt><dd>{{ target ? number(target.planned_base_qty) : '—' }}</dd></div><div><dt>设备编号</dt><dd>{{ deviceText }}</dd></div><div><dt>工序</dt><dd>{{ task.operation_name_snapshot }}</dd></div><div><dt>当前状态</dt><dd>{{ target ? target.status_label : '—' }}</dd></div></dl></div>
        <div v-if="targets.length > 1" class="ptw-target-picker"><label>执行对象</label><el-select :value="selectedKey" size="small" placeholder="请选择本次办理的执行对象" :disabled="locked" @change="changeTarget"><el-option v-for="row in targets" :key="targetKey(row)" :value="targetKey(row)" :disabled="row.missing" :label="targetLabel(row)" /></el-select></div>
        <div v-if="pending.length" class="ptw-pending"><el-alert title="上次操作结果尚未确认，保留原数量、对象和版本。" type="warning" :closable="false" show-icon /><el-button v-for="job in pending" :key="job.method + job.path" size="small" :loading="busy" @click="recover(job)">重试原操作</el-button></div>
        <template v-if="target">
          <section class="ptw-step-card"><el-steps :active="stepIndex" align-center finish-status="success"><el-step title="接单" :description="shortDate(target.claimed_at) || '待接单'" /><el-step title="齐套" :description="target.kitting_confirmed_at ? shortDate(target.kitting_confirmed_at) : target.kitting_required ? '待齐套' : '无需逐项确认'" /><el-step title="加工" :description="target.started_at ? laborText : '待开工'" /><el-step title="完工" :description="shortDate(target.completed_at) || '未完成'" /></el-steps></section>
          <el-alert v-if="target.reason_message" :title="target.reason_message" type="info" :closable="false" />
          <el-alert v-if="target.execution_integrity && !target.execution_integrity.valid" :title="target.execution_integrity.message" type="warning" :closable="false" />
          <section v-if="incomingRows.length" class="ptw-section"><h4>上道工序已交出（接单即验收）</h4><el-alert title="请核对产出数量和设备编号；接单即视为已验收。数量不齐或有问题，请先点“退回上道工序”。" type="warning" :closable="false" show-icon /><el-table :data="incomingRows" border size="mini" max-height="220"><el-table-column label="设备编号" min-width="120" prop="device_no" /><el-table-column label="产出单号" min-width="150" prop="output_no" /><el-table-column label="数量" width="80"><template slot-scope="{row}">{{ number(row.output_base_qty) }}</template></el-table-column><el-table-column label="交出人" min-width="90"><template slot-scope="{row}">{{ row.handed_over_by && row.handed_over_by.display_name || '—' }}</template></el-table-column><el-table-column label="交出时间" min-width="135"><template slot-scope="{row}">{{ shortDate(row.handed_over_at) || '—' }}</template></el-table-column></el-table></section>
          <section class="ptw-section"><h4>物料齐套情况</h4><el-alert v-if="materialError" :title="materialError" type="info" :closable="false" /><el-table v-else :data="materials" border size="mini" v-loading="materialsLoading" :empty-text="target.kitting_required ? '本工序暂无逐项齐套物料' : '本工序无需逐项齐套确认'" max-height="280"><el-table-column type="index" label="序号" width="48" /><el-table-column prop="component_item_name" label="物料名称" min-width="135" /><el-table-column label="规格型号" min-width="100"><template slot-scope="{row}">{{ row.cut_length_mm != null ? row.cut_length_mm + ' mm' : (row.component_item_spec || '—') }}</template></el-table-column><el-table-column label="计划用量" width="94"><template slot-scope="{row}">{{ number(row.required_base_qty) }}</template></el-table-column><el-table-column label="已领数量" width="94"><template slot-scope="{row}">{{ number(row.satisfied_base_qty) }}</template></el-table-column><el-table-column label="状态" width="88"><template slot-scope="{row}"><el-tag size="mini" :type="Number(row.shortage_base_qty) > 0 ? 'warning' : 'success'">{{ Number(row.shortage_base_qty) > 0 ? '待齐套' : '已齐套' }}</el-tag></template></el-table-column></el-table></section>
          <section v-if="receivedComponents.length" class="ptw-section">
            <h4>已接收下料明细</h4>
            <el-alert v-if="receivedTraceError" :title="receivedTraceError" type="warning" :closable="false" />
            <el-table :data="receivedComponents" border size="mini" max-height="260">
              <el-table-column label="原材料" min-width="130"><template slot-scope="{row}">{{ row.raw_item_name || row.raw_item_code || '资料待核对' }}</template></el-table-column>
              <el-table-column label="实际规格" min-width="130"><template slot-scope="{row}">{{ receivedSpecification(row) }}</template></el-table-column>
              <el-table-column label="已接收" min-width="85"><template slot-scope="{row}">{{ receivedQuantity(row,'received_qty') }}</template></el-table-column>
              <el-table-column label="已耗用" min-width="85"><template slot-scope="{row}">{{ receivedQuantity(row,'consumed_qty') }}</template></el-table-column>
              <el-table-column label="当前可用" min-width="85"><template slot-scope="{row}">{{ receivedQuantity(row,'available_qty') }}</template></el-table-column>
              <el-table-column label="交接来源" min-width="155"><template slot-scope="{row}">{{ row.handover_no || '待核对交接单' }}<span class="ptw-subtext">{{ row.output_no || '待核对产出单' }}</span></template></el-table-column>
            </el-table>
          </section>
          <section v-if="stationRows.length && allowed('confirm_kitting')" class="ptw-section"><h4>工位常备料盘点</h4><div v-for="row in stationRows" :key="row.id" class="ptw-form-row"><label>{{ row.component_item_name }}</label><el-input v-model="stationCounts[row.id]" size="small" inputmode="decimal" placeholder="填写实际可用数量" :disabled="locked" /></div></section>
          <production-cutting-operation-panel ref="cutting" v-if="target.cutting_required && $can('production.cutting.record') && target.my_role === 'owner'" :key="task.id + ':' + selectedKey" :task="task" :target="target" :disabled="locked" @updated="reload" @busy="cuttingBusy=$event" @dirty="cuttingDirty=$event" />
          <el-alert v-else-if="target.cutting_required" title="本工序按实际下料结果完成，由负责人登记加工用料和结果。" type="info" :closable="false" />
          <section class="ptw-section ptw-attachments"><h4><i class="el-icon-document" /> 工艺附件</h4><el-button v-for="file in attachments" :key="file.id" type="text" size="small" :loading="readingAttachment === file.id" @click="openAttachment(file)"><i class="el-icon-document" /> {{ file.original_name }}</el-button><span v-if="!attachments.length" class="ptw-muted">暂无工艺附件</span></section>
          <section class="ptw-section"><div class="ptw-section-title"><h4>作业人员（{{ workers.length }}人）</h4><el-button v-if="task.allowed_actions && task.allowed_actions.add_collaborators" type="success" plain size="mini" icon="el-icon-circle-plus-outline" :disabled="locked" @click="openCollaborators">添加协同</el-button></div><div class="ptw-crew"><div v-for="person in workers" :key="person.id" class="ptw-crew-person"><el-avatar :size="28" :src="person.avatar || ''" icon="el-icon-user" /><strong>{{ person.name }}</strong><el-tag size="mini" :type="person.owner ? 'success' : 'info'">{{ person.owner ? '操作工' : '协同' }}</el-tag></div></div><p class="ptw-labor"><i class="el-icon-time" /> 本人工时：{{ laborText }}<span>{{ target.my_labor && target.my_labor.status === 'ACTIVE' ? '计时中' : '未在计时' }}</span></p></section>
          <section v-if="reportVisible" class="ptw-section"><h4>登记报工</h4><p class="ptw-muted">本次可报余量 {{ number(target.remaining_base_qty) }}，按实际完成数量登记。</p><div class="ptw-report-grid"><label>合格数量<el-input v-model="report.qualified_base_qty" inputmode="decimal" size="small" :disabled="locked" /></label><label>不合格数量<el-input v-model="report.unqualified_base_qty" inputmode="decimal" size="small" :disabled="locked" /></label><label>报废数量<el-input v-model="report.scrapped_base_qty" inputmode="decimal" size="small" :disabled="locked" /></label></div><el-input v-model.trim="report.defect_reason" size="small" type="textarea" :rows="2" maxlength="1000" placeholder="有不合格或报废时填写实际原因" :disabled="locked" /><el-checkbox v-model="report.end_labor" :disabled="locked">本次报工后结束本人工时</el-checkbox><div class="ptw-inline-actions"><el-button size="small" :disabled="locked" @click="reportVisible=false">取消报工</el-button><el-button size="small" type="success" :disabled="locked" @click="submitReport">确认报工</el-button></div></section>
          <section v-if="completeVisible && !target.cutting_required" class="ptw-section"><h4>完成本工序</h4><p v-if="target.target_type === 'quantity_operation'">已报合格 {{ number(target.completed_base_qty) }} · 不合格 {{ number(target.unqualified_base_qty) }} · 报废 {{ number(target.scrapped_base_qty) }}</p><p v-else>请确认当前产品已按工艺要求完成。</p><el-radio-group v-if="target.output_mode_snapshot === 'warehouse_optional'" v-model="disposition" :disabled="locked"><el-radio label="direct_handover">直接交接</el-radio><el-radio label="warehouse">先入库</el-radio></el-radio-group><p v-else class="ptw-muted">{{ target.output_mode_snapshot === 'warehouse_required' ? '按工艺要求办理入库。' : '按工艺要求交接后续工序。' }}</p><div class="ptw-inline-actions"><el-button size="small" :disabled="locked" @click="completeVisible=false">取消</el-button><el-button size="small" type="success" :disabled="locked" @click="completeTarget">确认完成本工序</el-button></div></section>
        </template>
      </template>
    </div>
    <span slot="footer" class="ptw-footer"><el-button v-if="task && $can('production.completion.create')" type="text" size="small" :disabled="locked || hasUnsaved" @click="$refs.completion.open(task.work_order_id)">提交工单完工</el-button><span class="ptw-footer-actions"><el-button size="small" :disabled="busy || cuttingBusy" @click="close">关闭</el-button><el-button v-if="task && task.allowed_actions && task.allowed_actions.claim" size="small" type="success" :disabled="locked" @click="claim">{{ incomingRows.length ? '验收并接单' : '接单' }}</el-button><template v-if="task && task.pending_assignment"><el-button v-if="task.allowed_actions.reject_assignment" size="small" :disabled="locked" @click="decideAssignment(false)">拒绝派单</el-button><el-button v-if="task.allowed_actions.accept_assignment" size="small" type="success" :disabled="locked" @click="decideAssignment(true)">{{ incomingRows.length ? '验收并接受派单' : '接受派单' }}</el-button></template><el-button v-if="task && task.allowed_actions && task.allowed_actions.return_previous" size="small" type="warning" plain :disabled="locked" @click="returnPrevious">退回上道工序</el-button><el-button v-for="action in targetActions" :key="action.code" size="small" :type="action === targetActions[0] ? 'success' : 'default'" :disabled="locked || cuttingDirty" @click="runAction(action.code)">{{ action.label }}</el-button></span></span>
    <el-dialog title="选择协同人员" :visible.sync="collaboration.visible" width="680px" custom-class="production-task-dialog" append-to-body :close-on-click-modal="false" :show-close="!busy"><div class="ptw-filters"><el-input v-model.trim="collaboration.keyword" size="small" clearable placeholder="姓名或账号" :disabled="locked" @keyup.enter.native="loadCollaborators(1)" /><el-button size="small" :disabled="locked" @click="loadCollaborators(1)">查询</el-button></div><el-checkbox-group v-model="collaboration.ids" :disabled="locked" @change="refreshShares"><div v-for="person in collaboration.rows" :key="person.user_id" class="ptw-candidate"><el-checkbox :label="person.user_id" :disabled="person.already_joined || collaboration.ids.length >= 20 && !collaboration.ids.includes(person.user_id)">{{ person.display_name }} · {{ person.department_name || '未配置部门' }}</el-checkbox></div></el-checkbox-group><el-pagination layout="total, prev, pager, next" :current-page="collaboration.page" :page-size="10" :total="collaboration.total" @current-change="loadCollaborators" /><p class="ptw-muted">已选 {{ collaboration.ids.length }} 人，翻页保留，每次最多20人。</p><el-tag v-for="id in collaboration.ids" :key="id" size="small" :closable="!locked" @close="removeCollaborator(id)">{{ collaboration.people[id] && collaboration.people[id].display_name || '已选人员' }}</el-tag><section v-for="group in collaboration.groups" :key="group.scope_type + ':' + group.scope_id" class="ptw-section"><div class="ptw-section-title"><h4>{{ group.name }} · 个人份额</h4><el-button size="mini" :disabled="locked" @click="equalShares(group)">平均分配</el-button></div><div v-for="person in group.rows" :key="person.employee_legacy_id" class="ptw-form-row"><label>{{ person.employee_name }}</label><el-input v-model="person.percent" size="small" :disabled="locked"><span slot="append">%</span></el-input></div></section><span slot="footer"><el-button size="small" :disabled="busy" @click="collaboration.visible=false">关闭</el-button><el-button size="small" type="success" :disabled="locked || !collaboration.groups.length || collaboration.ids.length > 20" @click="saveCollaborators">确认协同人员</el-button></span></el-dialog>
    <work-order-completion-submit-dialog ref="completion" @updated="reload" />
  </el-dialog>
</template>

<script>
import { executionBase, targetPath, getExecutionTask, getKittingRequirements, writeExecutionCommand, pendingExecutionCommands, retryExecutionCommand } from '@/api/erp/production-execution'
import { listTaskCollaboratorCandidates } from '@/api/erp/production-assignments'
import { personalShareGroups, buildPersonalScopeShares, defaultPerformanceShares, ratioToPercent } from '@/utils/production-performance.mjs'
import { readWorkOrderTechnicalAttachment } from '@/api/erp/production'
import ProductionCuttingOperationPanel from './ProductionCuttingOperationPanel.vue'
import WorkOrderCompletionSubmitDialog from './WorkOrderCompletionSubmitDialog.vue'

export default {
  name:'ProductionTaskDetailDialog', components:{ProductionCuttingOperationPanel,WorkOrderCompletionSubmitDialog},
  data:()=>({visible:false,loading:false,busy:false,cuttingBusy:false,cuttingDirty:false,error:'',task:null,taskId:0,selectedKey:'',sequence:0,materialSequence:0,materials:[],materialsLoading:false,materialError:'',stationCounts:{},pending:[],receivedAt:0,now:Date.now(),readingAttachment:null,reportVisible:false,completeVisible:false,disposition:'direct_handover',report:{qualified_base_qty:'',unqualified_base_qty:'',scrapped_base_qty:'',defect_reason:'',end_labor:false},collaboration:{visible:false,keyword:'',page:1,total:0,rows:[],ids:[],people:{},groups:[],sequence:0}}),
  computed:{
    targets(){return this.task?.target_details || []}, target(){return this.targets.find(row=>this.targetKey(row)===this.selectedKey) || null},
    productName(){return this.task?.production_context?.product?.item_name || this.task?.work_order?.output_item?.item_name || '未提供产品名称'},
    locked(){return this.loading || this.busy || this.cuttingBusy || this.pending.length>0},
    hasUnsaved(){return this.cuttingDirty || this.reportVisible && ['qualified_base_qty','unqualified_base_qty','scrapped_base_qty','defect_reason'].some(key=>this.report[key]!=='') || Object.values(this.stationCounts).some(value=>value!=='')},
    attachments(){return this.task?.work_order?.technical_snapshot?.attachments || []},
    stationRows(){return this.materials.filter(row=>row.source_facts?.supply_mode==='workstation_stock')},
    receivedComponents(){return (this.task?.received_cutting_components||[]).filter(row=>row.target_type===this.target?.target_type&&Number(row.target_id)===Number(this.target?.target_id))},
    receivedTraceError(){return this.receivedComponents.find(row=>row.trace_status!=='verified')?.trace_message || (this.receivedComponents.some(row=>row.trace_status!=='verified')?'部分下料接收资料待核对，请先核对实际来源。':'')},
    workers(){if(!this.task)return [];const owner=this.task.assignee_user; const result=owner?[{id:this.task.assignee_user_legacy_id,name:owner.display_name,avatar:owner.avatar,owner:true}]:[];return result.concat((this.task.collaborators||[]).filter(row=>row.left_at==null && Number(row.employee_legacy_id)!==Number(this.task.assignee_user_legacy_id)).map(row=>({id:row.employee_legacy_id,name:row.employee?.display_name || '未提供姓名',avatar:row.employee?.avatar,owner:false})))},
    stepIndex(){if(!this.target)return 0;if(this.target.completed_at)return 4;if(this.target.started_at)return 2;if(!this.target.claimed_at&&!this.task?.assignee_user_legacy_id)return 0;if(this.target.kitting_confirmed_at || !this.target.kitting_required)return 2;return 1},
    laborText(){const labor=this.target?.my_labor;if(!labor || (!labor.accumulated_seconds && labor.status!=='ACTIVE'))return '未开始';const seconds=Math.max(0,Number(labor.accumulated_seconds||0)+(labor.status==='ACTIVE'?Math.floor((this.now-this.receivedAt)/1000):0));return `${Math.floor(seconds/3600).toString().padStart(2,'0')}:${Math.floor(seconds/60%60).toString().padStart(2,'0')}:${Math.floor(seconds%60).toString().padStart(2,'0')}`},
    targetActions(){if(!this.target)return [];return [this.target.primary_action,...(this.target.secondary_actions||[])].filter(action=>action && !(this.target.cutting_required && action.code==='complete'))},
    incomingRows(){return this.targets.flatMap(row=>(row.incoming_handovers||[]).map(item=>({...item,device_no:row.serial_no||row.production_unit_no||'—',target_label:this.targetLabel(row)})))},
    deviceText(){const list=[...new Set(this.targets.map(row=>row.serial_no||row.production_unit_no).filter(Boolean))];if(!list.length)return '—';return list.length>3?`${list.slice(0,3).join('、')} 等${list.length}台`:list.join('、')}
  },
  created(){this.timer=setInterval(()=>{this.now=Date.now()},1000);this.blobUrls=[];this.collaborationSequence=0},
  beforeDestroy(){clearInterval(this.timer);this.sequence++;this.materialSequence++;this.collaborationSequence++;this.blobUrls.forEach(url=>URL.revokeObjectURL(url))},
  methods:{
    number(value){return value==null?'—':Number(value).toLocaleString('zh-CN',{maximumFractionDigits:8})}, shortDate(value){return value?String(value).slice(0,10):''},
    receivedQuantity(row,field){if(row.trace_status!=='verified'||row[field]==null)return '待核对';const unit=row.quantity_unit==='m'?'m':row.quantity_unit==='piece'?'件':'';return this.number(row[field])+(unit?' '+unit:'')},
    receivedSpecification(row){if(row.trace_status!=='verified')return '待核对';const size=row.dimensions||{};const dimensions=[size.length_mm,size.width_mm,size.thickness_mm].filter(value=>value!=null);return dimensions.length?dimensions.join(' × ')+' mm':row.raw_item_spec||'—'},
    targetKey(row){return `${row.target_type}:${row.target_id}`}, targetLabel(row){return `${row.production_unit_no || row.serial_no || (row.target_type==='quantity_operation'?'数量作业':'逐件作业')} · ${row.status_label || '资料待核对'}`}, allowed(action){return !!this.target?.allowed_actions?.[action]},
    refreshPending(){this.pending=pendingExecutionCommands().filter(job => Number(job.task_id) === Number(this.taskId) || job.path === `${executionBase}/tasks/${this.taskId}` || job.path.startsWith(`${executionBase}/tasks/${this.taskId}/`))},
    async canDiscard(){if(this.busy||this.cuttingBusy)return false;if(!this.hasUnsaved)return true;try{await this.$confirm('有实际数量尚未保存，确认放弃这些未保存内容？','离开当前作业',{type:'warning'});return true}catch(_){return false}},
    async close(){if(await this.canDiscard())this.visible=false},async beforeClose(done){if(await this.canDiscard())done()},
    async open(id){if(this.visible&&!await this.canDiscard())return;if(this.busy||this.cuttingBusy)return;this.taskId=id;this.task=null;this.selectedKey='';this.cuttingDirty=false;this.stationCounts={};this.error='';this.visible=true;this.reportVisible=false;this.completeVisible=false;this.collaboration.visible=false;await this.reload()},
    closed(){this.sequence++;this.materialSequence++;this.materials=[];this.materialError='';this.stationCounts={};this.cuttingDirty=false;this.collaboration.visible=false;this.$emit('updated')},
    async reload(){const sequence=++this.sequence;this.loading=true;this.error='';try{this.refreshPending();const response=await getExecutionTask(this.taskId);if(sequence!==this.sequence||!this.visible)return;this.task=response.data.data;this.receivedAt=Date.now();this.now=this.receivedAt;if(!this.targets.some(row=>this.targetKey(row)===this.selectedKey))this.selectedKey=this.targets.length===1&&!this.targets[0].missing?this.targetKey(this.targets[0]):'';await this.loadMaterials();this.$emit('updated')}catch(error){if(sequence===this.sequence)this.error=error.userMessage||error.message}finally{if(sequence===this.sequence)this.loading=false}},
    async changeTarget(key){if(!await this.canDiscard())return;this.selectedKey=key;this.cuttingDirty=false;this.reportVisible=false;this.completeVisible=false;this.stationCounts={};await this.loadMaterials()},
    async loadMaterials(){const target=this.target;const key=this.selectedKey;const sequence=++this.materialSequence;const counts=this.stationCounts;this.materials=[];this.materialsLoading=false;this.materialError='';this.stationCounts={};if(!target)return;if(!this.$can('production.kitting.view')||target.my_role!=='owner'){this.materialError='齐套物料由本工序负责人核对。';return}this.materialsLoading=true;try{const response=await getKittingRequirements(this.taskId,target);if(sequence!==this.materialSequence||key!==this.selectedKey||!this.visible)return;this.materials=response.data.data||[];this.stationRows.forEach(row=>this.$set(this.stationCounts,row.id,Object.hasOwn(counts,row.id)?counts[row.id]:''))}catch(error){if(sequence===this.materialSequence)this.materialError=error.userMessage||error.message}finally{if(sequence===this.materialSequence)this.materialsLoading=false}},
    async send(path,id,payload,method='POST'){
      if(this.busy)return false;if(this.cuttingDirty){this.$message.error('请先保存本批实际下料结果');return false}this.busy=true;this.error=''
      try{await writeExecutionCommand(method,path,id,payload,{task_id:this.taskId});if(path.endsWith('/report'))this.reportVisible=false;if(path.endsWith('/complete'))this.completeVisible=false;this.$message.success('操作已完成');await this.reload();return true}
      catch(error){
        if(error.errorCode==='labor_switch_confirmation_required'&&!error.pendingCommand){const details=error.response?.data?.details||{};const active=details.active_labor_session||details.active_session||details;const sessionId=active.session_id||active.id||details.active_labor_session_id;this.busy=false;try{await this.$confirm(error.userMessage||'已有其他任务正在计时，确认暂停原作业并切换到当前任务？','切换本人计时',{type:'warning'});if(!sessionId)throw new Error('当前工时身份未返回，请重新核对');return await this.send(path,id,{...error.executionCommand.payload,switch_active_labor:true,expected_active_labor_session_id:Number(sessionId)},method)}catch(confirmError){if(confirmError!=='cancel'&&confirmError!=='close')this.error=confirmError.userMessage||confirmError.message||'未切换计时';return false}}
        this.error=error.userMessage||error.message;this.refreshPending();return false
      }finally{this.busy=false}
    },
    async recover(job){if(this.busy)return;this.busy=true;try{await retryExecutionCommand(job);if(job.path.endsWith('/report'))this.reportVisible=false;if(job.path.endsWith('/complete'))this.completeVisible=false;if(job.path.endsWith('/collaborators'))this.collaboration.visible=false;this.$message.success('原操作结果已确认');await this.reload();await this.$nextTick();if(job.path.includes('/cutting/')&&this.$refs.cutting)await this.$refs.cutting.load()}catch(error){this.error=error.userMessage||error.message;this.refreshPending()}finally{this.busy=false}},
    async confirmReceive(title){if(!this.incomingRows.length)return true;try{await this.$confirm('请确认已核对上道工序交来的产出（数量、设备编号）。确认后视为已验收并接单；有问题请取消，改点“退回上道工序”。',title,{type:'warning',confirmButtonText:'确认验收并接单',cancelButtonText:'再核对'});return true}catch(_){return false}},
    async claim(){if(this.locked||!this.task.allowed_actions.claim)return;if(!await this.confirmReceive('验收并接单'))return;this.send(`${executionBase}/tasks/${this.task.id}/claim`,this.task.id,{expected_version:this.task.business_version})},
    async returnPrevious(){if(this.locked)return;if(this.targets.length>1&&!this.target)return this.$message.error('请先选择需要退回的执行对象');const rows=(this.target?this.target.incoming_handovers:this.targets.flatMap(row=>row.incoming_handovers||[]))||[];if(!rows.length)return this.$message.error('没有可退回的上道工序交出');let reason='';try{const result=await this.$prompt('请填写退回上道工序的原因（如数量不齐、设备编号不符、外观不良）','退回上道工序',{inputType:'textarea',inputValidator:value=>String(value||'').trim()?true:'请填写退回原因',confirmButtonText:'确认退回',cancelButtonText:'取消'});reason=String(result.value||'').trim()}catch(_){return}for(const item of rows){const ok=await this.send(`${executionBase}/handovers/${item.id}/reject`,item.id,{expected_version:item.business_version,reason});if(!ok)break}},
    async decideAssignment(accept){if(this.locked)return;const assignment=this.task.pending_assignment;let reason='';if(!assignment)return;if(accept&&!await this.confirmReceive('验收并接受派单'))return;try{if(!accept){const result=await this.$prompt('请填写拒绝派单原因（可选）','拒绝派单',{inputType:'textarea'});reason=String(result.value||'').trim()}}catch(_){return}this.send(`${executionBase}/assignments/${assignment.id}/${accept?'accept':'reject'}`,assignment.id,{expected_version:assignment.business_version,expected_task_version:this.task.business_version,...(accept?{}:{reason})})},
    async runAction(code){if(this.locked||!this.target)return;if(['accept_handover','open_job_bundle','report','complete'].includes(code)&&!await this.canDiscard())return;if(code==='accept_handover'){const rows=this.target.incoming_handovers||[];if(!rows.length)return this.$message.error('没有待验收的上道工序产出；如果是下料产出，请到下料交接中接收。');if(!await this.confirmReceive('验收上道工序产出'))return;for(const item of rows){const ok=await this.send(`${executionBase}/handovers/${item.id}/accept`,item.id,{expected_version:item.business_version});if(!ok)break}return}if(code==='open_job_bundle'){if(this.$can('production.work_order.view')){this.visible=false;this.$router.push({path:`/production/work-orders/${this.task.work_order_id}`,query:{tab:'bundles'}})}else this.error='本任务已加入共同加工作业，请由有权限的人员在工单共同加工中办理。';return}if(code==='report'){this.report={qualified_base_qty:'',unqualified_base_qty:'',scrapped_base_qty:'',defect_reason:'',end_labor:false};this.reportVisible=true;this.completeVisible=false;return}if(code==='complete'){if(this.target.target_type==='quantity_operation'&&Number(this.target.remaining_base_qty)>0.00000001)return this.$message.error('请先登记全部实际报工数量，再完成本工序');this.completeVisible=true;this.reportVisible=false;this.disposition=this.target.output_mode_snapshot==='warehouse_required'?'warehouse':'direct_handover';return}
      const actions={confirm_kitting_and_start:'confirm-kitting',start:'start',start_rework:'rework/start',pause_my_work:'pause',resume_my_work:'resume',start_collaborator_labor:'collaborator-labor/start',pause_collaborator_labor:'collaborator-labor/pause'};const suffix=actions[code];if(!suffix)return;const payload={expected_version:this.target.business_version};if(code==='confirm_kitting_and_start'){if(this.materialsLoading||this.materialError)return this.$message.error('请先完成齐套物料核对');if(this.stationRows.some(row=>!/^\d+(?:\.\d{1,8})?$/.test(String(this.stationCounts[row.id]))))return this.$message.error('请填写每项常备料的实际可用数量');payload.workstation_stock_confirmations=this.stationRows.map(row=>({requirement_id:row.id,onsite_available_base_qty:this.stationCounts[row.id]}))}await this.send(`${targetPath(this.task.id,this.target)}/${suffix}`,this.target.target_id,payload)
    },
    async submitReport(){if(this.locked||!this.allowed('report'))return;const amounts=['qualified_base_qty','unqualified_base_qty','scrapped_base_qty'];if(amounts.some(key=>!/^\d+(?:\.\d{1,8})?$/.test(String(this.report[key]))))return this.$message.error('请明确填写合格、不合格和报废数量，无则填0');const sum=amounts.reduce((value,key)=>value+Number(this.report[key]),0);if(sum<=0||sum>Number(this.target.remaining_base_qty)+0.00000001)return this.$message.error('本次报工合计须大于0且不能超过可报余量');if((Number(this.report.unqualified_base_qty)>0||Number(this.report.scrapped_base_qty)>0)&&!this.report.defect_reason)return this.$message.error('请填写不合格或报废原因');await this.send(`${targetPath(this.task.id,this.target)}/report`,this.target.target_id,{expected_version:this.target.business_version,...this.report})},
    completeTarget(){if(this.locked||!this.allowed('complete')||this.target.cutting_required)return;if(this.target.target_type==='quantity_operation'&&Number(this.target.remaining_base_qty)>0.00000001)return this.$message.error('请先登记全部实际报工数量，再完成本工序');this.send(`${targetPath(this.task.id,this.target)}/complete`,this.target.target_id,{expected_version:this.target.business_version,disposition:this.disposition})},
    async openAttachment(file){if(this.readingAttachment!==null)return;this.readingAttachment=file.id;const preview=window.open('','_blank');try{const response=await readWorkOrderTechnicalAttachment(this.task.work_order_id,file.id,false);const url=URL.createObjectURL(response.data);this.blobUrls.push(url);if(preview)preview.location.href=url;else{const link=document.createElement('a');link.href=url;link.download=file.original_name;link.click()}}catch(error){if(preview)preview.close();this.$message.error(error.userMessage||'附件读取失败')}finally{this.readingAttachment=null}},
    openCollaborators(){if(this.locked)return;this.collaboration={visible:true,keyword:'',page:1,total:0,rows:[],ids:[],people:{},groups:[],sequence:0};this.refreshShares();this.loadCollaborators(1)},
    async loadCollaborators(page){if(this.locked)return;const sequence=++this.collaborationSequence;this.collaboration.page=page;try{const response=await listTaskCollaboratorCandidates(this.task.id,{keyword:this.collaboration.keyword,page,per_page:10});if(sequence!==this.collaborationSequence||!this.collaboration.visible)return;this.collaboration.rows=response.data.data||[];this.collaboration.total=Number(response.data.total||0);this.collaboration.rows.forEach(person=>this.$set(this.collaboration.people,person.user_id,person))}catch(error){if(sequence===this.collaborationSequence)this.error=error.userMessage||error.message}},
    refreshShares(){if(this.locked)return;this.collaboration.groups=personalShareGroups(this.task.share_scopes||[],this.collaboration.ids.map(id=>this.collaboration.people[id]),this.collaboration.groups)},
    removeCollaborator(id){if(this.locked)return;this.collaboration.ids=this.collaboration.ids.filter(value=>Number(value)!==Number(id));this.refreshShares()},
    equalShares(group){if(this.locked)return;const shares=defaultPerformanceShares(group.rows);group.rows.forEach(person=>{person.percent=ratioToPercent(shares.find(share=>share.employee_legacy_id===Number(person.employee_legacy_id)).share_ratio)})},
    async saveCollaborators(){if(this.locked||!this.task.allowed_actions?.add_collaborators||this.collaboration.ids.length>20)return;let shares;try{shares=buildPersonalScopeShares(this.collaboration.groups)}catch(error){return this.$message.error(error.message)}if(await this.send(`${executionBase}/tasks/${this.task.id}/collaborators`,this.task.id,{expected_version:this.task.business_version,employee_legacy_ids:this.collaboration.ids,scope_shares:shares}))this.collaboration.visible=false}
  }
}
</script>

